/**
 * Константы, которые подставляет сборщик (`define` в vite.config.ts).
 *
 * Объявлены глобально, а не в каждом файле по месту: `__DEV_BUILD__` нужен и
 * `version.ts`, и точке входа, а два независимых объявления одного и того же
 * — это две возможности разойтись.
 */

/** Версия из package.json. */
declare const __VERSION__: string;
/** Короткий git-SHA сборки. */
declare const __GIT_SHA__: string;
/**
 * Дев-сборка. ПОДСТАВЛЯЕТСЯ ЛИТЕРАЛОМ, и это важно: ветка `if (__DEV_BUILD__)`
 * в релизе превращается в `if (false)` ещё до разбора, поэтому всё внутри неё
 * — включая динамические импорты — выбрасывается гарантированно.
 */
declare const __DEV_BUILD__: boolean;
